// Сгенерировано из design/logo/reloom-white.svg — контуры перенесены как есть.
// Исходники остаются источником правды: при смене логотипа перегенерировать,
// а не править контуры руками.
//
// В цветных SVG знак начинается с отступом ~80px от края viewBox — это запас
// под свечение. Здесь свечение не воспроизводится (оно вешается отдельно,
// токеном --glow-brand и только на статике), поэтому viewBox обрезан по
// содержимому и логотип выравнивается по своему оптическому краю.

export type LogoVariant = 'lockup' | 'mark'

/**
 * Как раскрашен логотип.
 *
 * `duo` — основной вид в интерфейсе: знак фирменным фиолетовым градиентом,
 * надпись цветом текста. На тёмной теме это фиолетовый знак и белая
 * надпись, на светлой — тот же знак и тёмная надпись. Один вариант
 * работает в обеих темах, и выбирать его на каждом экране не нужно.
 *
 * Зелёного варианта здесь нет намеренно. Он существует в исходниках
 * (design/logo/reloom-green.svg) и годится для печати и сувениров, но
 * в интерфейсе не используется: акцент у нас работает заливкой под
 * тёмным текстом, а зелёная надпись на тёмном фоне уводит бренд
 * в другую сторону.
 */
export type LogoTone = 'current' | 'brand' | 'duo'

