// Диагональ как в design/logo/reloom-purple.svg: светлый верх-право -> тёмный низ-лево.
const BRAND_STOPS: [string, string] = ['var(--brand-light)', 'var(--brand-dark)']

export interface LogoProps {
  variant?: LogoVariant
  tone?: LogoTone
  /** Высота в пикселях. Знак не бывает меньше 24px — требование docs/brand.md. */
  height?: number
  title?: string
  className?: string
}

export function Logo({
  variant = 'lockup',
  tone = 'current',
  height = 32,
  title,
  className,
}: LogoProps) {
  const isLockup = variant === 'lockup'
  const viewBox = isLockup ? '0 0 1133 291' : '0 0 297 291'
  const width = Math.round((isLockup ? 1133 / 291 : 297 / 291) * height)
  // Градиент один на все экземпляры: определение совпадает до символа,
  // и плодить идентификаторы незачем.
  const gradientId = 'reloom-brand-gradient'
  const brandFill = `url(#${gradientId})`
  const markFill = tone === 'current' ? 'currentColor' : brandFill
  // В duo надпись берёт цвет текста: белая на тёмной теме, тёмная на светлой.
  const wordFill = tone === 'duo' ? 'currentColor' : markFill
  const needsGradient = tone !== 'current'

  return (
    <svg
      className={className}
      width={width}
      height={height}
      viewBox={viewBox}
      fill="none"
      role={title ? 'img' : 'presentation'}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      xmlns="http://www.w3.org/2000/svg"
    >
      {needsGradient ? (
        <defs>
          <linearGradient id={gradientId} x1="100%" y1="0%" x2="0%" y2="100%">
            <stop offset="0" stopColor={BRAND_STOPS[0]} />
            <stop offset="1" stopColor={BRAND_STOPS[1]} />
          </linearGradient>
        </defs>
      ) : null}
      <path d={MARK_A} fill={markFill} />
      <path d={MARK_B} fill={markFill} />
      {isLockup ? <path d={WORDMARK} fill={wordFill} /> : null}
    </svg>
  )
}
